<script setup>
import {onMounted,onUnmounted,ref} from 'vue'
import {createEquipmentReview,stages} from './scene3d/equipment-review-scene.js'
const host=ref(null),elapsed=ref(0),playing=ref(false),stage=ref(0),error=ref(''),camera=ref('all')
let scene
onMounted(()=>{try{scene=createEquipmentReview(host.value,value=>{elapsed.value=value.elapsed;playing.value=value.playing;stage.value=value.stage},message=>error.value=message)}catch{error.value='3D 화면을 불러오지 못했습니다. WebGL을 지원하는 브라우저에서 다시 열어 주세요.'}})
onUnmounted(()=>scene?.dispose())
function viewpoint(value){camera.value=value;scene?.view(value)}
function seek(value){scene?.seek(Number(value))}
</script>
<template>
 <main class="equipment-review">
  <header class="eq-header"><a href="/" class="eq-brand"><span>F</span> FACTORY <small>DESIGN LAB</small></a><nav><span class="eq-pill">MODEL STUDY / 02</span><a href="/?view=3d">실시간 관제 ↗</a></nav></header>
  <section class="eq-intro"><div><p class="eq-eyebrow">EQUIPMENT DETAIL STUDY</p><h1>한 대의 운반차.<br>하나의 조립 셀.</h1><p>형태를 넘어, 인계와 작업이 보이는 공장으로.</p></div><div class="eq-intro-note"><span>AGV–002 × ASM–01</span><p>밝은 바닥 · 코발트 블루 · 브러시드 메탈</p><small>외형과 동작을 확인하는 1차 시안</small></div></section>
  <div class="eq-layout">
   <section class="eq-stage" aria-label="상세 모델 미리보기">
    <div class="eq-stage-top"><span><i></i> 설비 디테일 시안</span><span>INTERACTIVE 3D</span></div>
    <div ref="host" class="eq-canvas"></div>
    <p v-if="error" role="alert" class="eq-error">{{error}}</p>
    <div class="eq-camera" aria-label="모델 시점"><button v-for="v in [{id:'all',name:'전체'},{id:'agv',name:'AGV 상세'},{id:'asm',name:'ASM 상세'},{id:'top',name:'평면'}]" :key="v.id" :aria-pressed="camera===v.id" @click="viewpoint(v.id)">{{v.name}}</button><span>드래그로 회전 · 휠로 확대</span></div>
    <div class="eq-playback"><button class="eq-play" @click="scene?.toggle()" :disabled="!!error">{{playing?'Ⅱ 일시정지':elapsed>=25?'↻ 다시 재생':'▶ 동작 보기'}}</button><label>동작 진행<input aria-label="시안 동작 진행" type="range" min="0" max="25" step="0.1" :value="elapsed" @input="seek($event.target.value)" /></label><output>{{elapsed.toFixed(1)}}<span> / 25s</span></output></div>
    <div class="eq-phases"><button v-for="(item,i) in stages" :key="item.name" :aria-pressed="stage===i" @click="seek(item.at)"><span>0{{i+1}}</span>{{item.name}}</button></div>
   </section>
   <aside class="eq-sidebar">
    <section class="eq-detail"><p class="eq-eyebrow">CURRENT SEQUENCE</p><div class="eq-step-number">0{{stage+1}}<span> / 04</span></div><h2>{{stages[stage].name}}</h2><p>{{stages[stage].description}}</p><div class="eq-line"></div><span class="eq-micro">DESIGN INTENT</span><p>차체가 갑자기 옮겨지지 않도록<br>롤러와 팔레트의 인계 과정을 표현합니다.</p></section>
    <section class="eq-spec"><p class="eq-eyebrow">살펴볼 디테일</p><button @click="viewpoint('agv')"><span>01</span><div><strong>AGV / 운반 플랫폼</strong><p>전면등 · 센서 · 범퍼<br>적재 롤러 · 휠 · 정비 패널</p></div><b>↗</b></button><button @click="viewpoint('asm')"><span>02</span><div><strong>ASM / 조립 스테이션</strong><p>이송 지그 · 고정 클램프<br>관절 로봇 · 제어반 · 안전 펜스</p></div><b>↗</b></button></section>
    <section class="eq-note"><span>i</span><p><strong>설계 확인용 동작입니다.</strong>실제 설비 도면에 기반한 모델이나 실시간 생산 데이터가 아닙니다. 형태와 인계 방식 확인 후 관제에 연결합니다.</p></section>
   </aside>
